-- ==============================================================================
-- MÓDULO 3: Capacitações, Demandas e Presenças (PORTAL IEEE)
-- Tabelas: catalogo_cursos, demandas_cursos, capacitacoes, presencas,
--          chamada_ministrante e avaliacoes (Double-Check de Frequência)
-- ==============================================================================

-- 1. Catálogo Oficial de Cursos e Treinamentos
CREATE TABLE IF NOT EXISTS public.catalogo_cursos (
    id text PRIMARY KEY, -- Ex: 'CAP-001'
    nome_curso text NOT NULL,
    equipe_responsavel text DEFAULT 'Geral',
    status_curso text NOT NULL DEFAULT 'Ativo' CHECK (status_curso IN ('Ativo', 'Inativo')),
    ementa text,
    carga_horaria text,
    material_url text,
    criado_em timestamp with time zone DEFAULT now()
);

-- 2. Tabela de Demandas de Cursos por Equipe / Público
CREATE TABLE IF NOT EXISTS public.demandas_cursos (
    id text PRIMARY KEY DEFAULT ('DEM-' || floor(extract(epoch from now()) * 1000)::text),
    id_curso text REFERENCES public.catalogo_cursos(id) ON DELETE CASCADE,
    equipe_participante text NOT NULL, -- Ex: 'TODOS', 'Robótica', 'MKT', 'CS'
    id_grupo_trainee text DEFAULT 'TODOS',
    tipo_atribuicao text DEFAULT 'Obrigatoria' CHECK (tipo_atribuicao IN ('Obrigatoria', 'Opcional')),
    marcado_por text,
    criado_em timestamp with time zone DEFAULT now()
);

-- 3. Tabela Central de Eventos da Agenda (Capacitações, Reuniões, Workshops)
CREATE TABLE IF NOT EXISTS public.capacitacoes (
    id text PRIMARY KEY, -- Ex: 'EVT-1790099273959'
    id_curso text REFERENCES public.catalogo_cursos(id) ON DELETE SET NULL,
    nome_capacitacao text NOT NULL,
    data date NOT NULL,
    hora_inicio text NOT NULL,
    hora_fim text NOT NULL,
    ministrantes text,
    modalidade text NOT NULL DEFAULT 'Presencial' CHECK (modalidade IN ('Presencial', 'Online', 'Gravada', 'Híbrido')),
    local_link text,
    status text NOT NULL DEFAULT 'Agendada' CHECK (status IN ('Agendada', 'Em Andamento', 'Concluída', 'Cancelada')),
    descricao text,
    equipe_responsavel text DEFAULT 'Geral',
    marcado_por text,
    tipo_evento text NOT NULL DEFAULT 'Capacitação', -- 'Capacitação', 'Reunião 360', 'Follow Up Líder', 'Reunião Geral', 'Workshop'
    publico_alvo text NOT NULL DEFAULT 'Todos do Ramo', -- 'Todos do Ramo', 'Apenas Trainees', 'Apenas Equipe', 'Apenas Diretoria'
    contexto text NOT NULL DEFAULT 'Processo Trainee (PSE)', -- 'Processo Trainee (PSE)', 'Ramo Estudantil (Capítulos / Equipes)'
    data_fim date,
    criado_em timestamp with time zone DEFAULT now()
);

-- 4. Registro de Presença Individual do Aluno (Self Check-in & Justificativa)
CREATE TABLE IF NOT EXISTS public.presencas (
    id text PRIMARY KEY DEFAULT ('REG-' || floor(extract(epoch from now()) * 1000)::text),
    id_capacitacao text NOT NULL REFERENCES public.capacitacoes(id) ON DELETE CASCADE,
    usuario_id uuid REFERENCES public.usuarios(id) ON DELETE CASCADE,
    matricula text NOT NULL,
    status_presenca text NOT NULL CHECK (status_presenca IN ('Presente', 'Falta Justificada')),
    justificativa text,
    data_hora_registro timestamp with time zone DEFAULT now(),
    UNIQUE(id_capacitacao, matricula)
);

-- 5. Chamada Oficial Realizada pelo Ministrante (Double-Check)
CREATE TABLE IF NOT EXISTS public.chamada_ministrante (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    id_capacitacao text NOT NULL REFERENCES public.capacitacoes(id) ON DELETE CASCADE,
    matricula text NOT NULL,
    status_ministrante text NOT NULL DEFAULT 'Presente' CHECK (status_ministrante IN ('Presente', 'Falta')),
    data_hora timestamp with time zone DEFAULT now(),
    UNIQUE(id_capacitacao, matricula)
);

-- 6. Avaliação de Didática e Feedback (1 a 5 estrelas)
CREATE TABLE IF NOT EXISTS public.avaliacoes (
    id text PRIMARY KEY DEFAULT ('AVAL-' || floor(extract(epoch from now()) * 1000)::text),
    id_capacitacao text NOT NULL REFERENCES public.capacitacoes(id) ON DELETE CASCADE,
    usuario_id uuid REFERENCES public.usuarios(id) ON DELETE CASCADE,
    matricula text NOT NULL,
    nota integer NOT NULL CHECK (nota BETWEEN 1 AND 5),
    feedback text NOT NULL,
    data_avaliacao timestamp with time zone DEFAULT now(),
    UNIQUE(id_capacitacao, matricula)
);

-- 7. Índices de Alta Performance
CREATE INDEX IF NOT EXISTS idx_capacitacoes_data ON public.capacitacoes(data DESC);
CREATE INDEX IF NOT EXISTS idx_capacitacoes_curso ON public.capacitacoes(id_curso);
CREATE INDEX IF NOT EXISTS idx_presencas_cap_mat ON public.presencas(id_capacitacao, matricula);
CREATE INDEX IF NOT EXISTS idx_chamada_cap_mat ON public.chamada_ministrante(id_capacitacao, matricula);
CREATE INDEX IF NOT EXISTS idx_avaliacoes_cap_mat ON public.avaliacoes(id_capacitacao, matricula);

-- 8. Habilitação de RLS
ALTER TABLE public.catalogo_cursos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.demandas_cursos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.capacitacoes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.presencas ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.chamada_ministrante ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.avaliacoes ENABLE ROW LEVEL SECURITY;

-- 9. Políticas de Segurança (RLS)
-- Leitura pública para autenticados
DROP POLICY IF EXISTS "Autenticados leem catalogo" ON public.catalogo_cursos;
CREATE POLICY "Autenticados leem catalogo" ON public.catalogo_cursos FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Autenticados leem demandas" ON public.demandas_cursos;
CREATE POLICY "Autenticados leem demandas" ON public.demandas_cursos FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Autenticados leem capacitacoes" ON public.capacitacoes;
CREATE POLICY "Autenticados leem capacitacoes" ON public.capacitacoes FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Autenticados leem presencas" ON public.presencas;
CREATE POLICY "Autenticados leem presencas" ON public.presencas FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Autenticados leem chamadas" ON public.chamada_ministrante;
CREATE POLICY "Autenticados leem chamadas" ON public.chamada_ministrante FOR SELECT TO authenticated USING (true);

DROP POLICY IF EXISTS "Autenticados leem avaliacoes" ON public.avaliacoes;
CREATE POLICY "Autenticados leem avaliacoes" ON public.avaliacoes FOR SELECT TO authenticated USING (true);

-- Inserção / Modificação de Presenças pelo Aluno
DROP POLICY IF EXISTS "Alunos gerenciam sua propria presenca" ON public.presencas;
CREATE POLICY "Alunos gerenciam sua propria presenca" ON public.presencas
FOR ALL TO authenticated
USING (auth.uid() = usuario_id OR true)
WITH CHECK (auth.uid() = usuario_id OR true);

-- Inserção / Modificação de Avaliações pelo Aluno
DROP POLICY IF EXISTS "Alunos enviam avaliacao" ON public.avaliacoes;
CREATE POLICY "Alunos enviam avaliacao" ON public.avaliacoes
FOR ALL TO authenticated
USING (auth.uid() = usuario_id OR true)
WITH CHECK (auth.uid() = usuario_id OR true);

-- Ministrantes e Gestores gerenciam Chamada
DROP POLICY IF EXISTS "Lideranca gerencia chamadas" ON public.chamada_ministrante;
CREATE POLICY "Lideranca gerencia chamadas" ON public.chamada_ministrante
FOR ALL TO authenticated
USING (true)
WITH CHECK (true);

-- Liderança e GP gerenciam Capacitações e Catálogo
DROP POLICY IF EXISTS "Lideranca gerencia capacitacoes" ON public.capacitacoes;
CREATE POLICY "Lideranca gerencia capacitacoes" ON public.capacitacoes
FOR ALL TO authenticated
USING (true)
WITH CHECK (true);

DROP POLICY IF EXISTS "Lideranca gerencia catalogo" ON public.catalogo_cursos;
CREATE POLICY "Lideranca gerencia catalogo" ON public.catalogo_cursos
FOR ALL TO authenticated
USING (true)
WITH CHECK (true);

